 const address={};for(const [key,value] of Object.entries({city:v('locality'),line1:[v('route'),v('street_number')].filter(Boolean).join(' '),state:v('admin_area_level_1'),country:country?.toUpperCase(),postal_code:v('postal_code')}))if(value!=null&&value!==''){if(typeof value!=='string')throw Error('Invalid address component');address[key]=value}
